package dev.atqiya.ledgerly.invoicing.application;
import dev.atqiya.ledgerly.invoicing.domain.*; import dev.atqiya.ledgerly.invoicing.infrastructure.*; import dev.atqiya.ledgerly.workspace.application.WorkspaceAccessService; import dev.atqiya.ledgerly.workspace.domain.*;
import java.math.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class InvoicingService{
 private static final Set<WorkspaceRole> EDITORS=Set.of(WorkspaceRole.OWNER,WorkspaceRole.ADMIN,WorkspaceRole.MEMBER);
 private final CustomerRepository customers;private final InvoiceRepository invoices;private final InvoicePaymentRepository payments;private final WorkspaceAccessService access;
 public InvoicingService(CustomerRepository c,InvoiceRepository i,InvoicePaymentRepository p,WorkspaceAccessService a){customers=c;invoices=i;payments=p;access=a;}
 @Transactional public CustomerView createCustomer(UUID u,UUID w,String name,String email,String phone,String address){var m=access.requireRole(u,w,EDITORS);String n=text(name,160,"Customer name");var c=new Customer(UUID.randomUUID(),m.getWorkspace(),n,optional(email,320),optional(phone,40),optional(address,500),m.getUser(),Instant.now());return CustomerView.from(customers.save(c));}
 @Transactional(readOnly=true) public List<CustomerView> customers(UUID u,UUID w){access.requireMembership(u,w);return customers.findAllByWorkspace_IdAndActiveTrueOrderByName(w).stream().map(CustomerView::from).toList();}
 @Transactional public InvoiceView createInvoice(UUID u,UUID w,UUID customerId,String number,LocalDate issue,LocalDate due,String notes,List<NewLine> lines){var m=access.requireRole(u,w,EDITORS);var c=customers.findByIdAndWorkspace_Id(customerId,w).filter(Customer::isActive).orElseThrow(()->new InvoicingException("Customer was not found."));if(issue==null||due==null||due.isBefore(issue))throw new InvoicingException("Due date must not precede issue date.");String no=text(number,60,"Invoice number");if(invoices.existsByWorkspace_IdAndInvoiceNumberIgnoreCase(w,no))throw new InvoicingException("Invoice number already exists.");var invoice=new Invoice(UUID.randomUUID(),m.getWorkspace(),c,no,issue,due,optional(notes,1000),m.getUser(),Instant.now());if(lines==null||lines.isEmpty())throw new InvoicingException("Invoice requires at least one line.");for(var l:lines){if(l.quantity()==null||l.quantity().signum()<=0||l.unitPrice()==null||l.unitPrice().signum()<0)throw new InvoicingException("Line quantity and price are invalid.");invoice.addLine(text(l.description(),200,"Line description"),l.quantity(),l.unitPrice());}return InvoiceView.from(invoices.save(invoice),LocalDate.now());}
 @Transactional(readOnly=true) public List<InvoiceView> list(UUID u,UUID w,Boolean overdue){access.requireMembership(u,w);LocalDate today=LocalDate.now();return invoices.findAllByWorkspace_IdOrderByIssueDateDescCreatedAtDesc(w).stream().filter(i->overdue==null||i.isOverdue(today)==overdue).map(i->InvoiceView.from(i,today)).toList();}
 @Transactional public InvoiceView send(UUID u,UUID w,UUID id){var m=access.requireRole(u,w,EDITORS);var i=require(w,id);act(()->i.send(m.getUser(),Instant.now()));return InvoiceView.from(i,LocalDate.now());}
 @Transactional public InvoiceView pay(UUID u,UUID w,UUID id,BigDecimal amount,LocalDate paidOn,String reference){var m=access.requireRole(u,w,EDITORS);var i=require(w,id);if(amount==null||amount.signum()<=0||paidOn==null)throw new InvoicingException("Payment amount and date are required.");Instant now=Instant.now();act(()->i.recordPayment(amount,m.getUser(),now));payments.save(new InvoicePayment(UUID.randomUUID(),i,amount,paidOn,optional(reference,120),m.getUser(),now));return InvoiceView.from(i,LocalDate.now());}
 @Transactional public InvoiceView voidInvoice(UUID u,UUID w,UUID id){var m=access.requireRole(u,w,EDITORS);var i=require(w,id);act(()->i.voidInvoice(m.getUser(),Instant.now()));return InvoiceView.from(i,LocalDate.now());}
 private Invoice require(UUID w,UUID id){return invoices.findByIdAndWorkspace_Id(id,w).orElseThrow(()->new InvoicingException("Invoice was not found."));} private void act(Runnable r){try{r.run();}catch(IllegalStateException e){throw new InvoicingException(e.getMessage());}}
 private String text(String v,int max,String label){if(v==null||v.strip().isEmpty()||v.strip().length()>max)throw new InvoicingException(label+" is invalid.");return v.strip().replaceAll("\\s+"," ");} private String optional(String v,int max){if(v==null||v.isBlank())return null;if(v.strip().length()>max)throw new InvoicingException("Value is too long.");return v.strip();}
 public record NewLine(String description,BigDecimal quantity,BigDecimal unitPrice){}
}
